<script setup>
import PartnerLayout from '@/Layouts/PartnerLayout.vue';import FormErrors from '@/Components/Partner/FormErrors.vue';import {useForm,Link} from '@inertiajs/vue3';
const props=defineProps({invoice:Object});const pay=useForm({});const manual=useForm({amount:props.invoice.balance,payment_method:'bank_transfer',transaction_reference:'',payment_date:new Date().toLocaleDateString('en-CA')});
</script>
<template><PartnerLayout :title="invoice.invoice_number"><Link :href="route('partner.invoices')" class="mb-5 inline-block text-cyan-700">Back to invoices</Link><div class="rounded-xl bg-white p-6"><h2 class="text-xl font-bold">{{ invoice.customer.name }}</h2><p>{{ invoice.customer.email }}</p><p class="mt-3 capitalize">{{ invoice.status }}</p><div class="mt-5 divide-y"><div v-for="item in invoice.items" :key="item.id" class="flex justify-between gap-5 py-4"><span>{{ item.description }}</span><strong>{{ invoice.currency }} {{ item.total }}</strong></div></div><dl class="mt-5 space-y-2"><div>Subtotal: {{ invoice.currency }} {{ invoice.subtotal }}</div><div>Discount: {{ invoice.currency }} {{ invoice.discount }}</div><div>{{ invoice.vat_rate != null ? 'VAT (' + Number(invoice.vat_rate) + '%)' : 'Tax' }}: {{ invoice.currency }} {{ invoice.tax }}</div></dl><p class="mt-5 text-lg font-bold">Total including tax: {{ invoice.currency }} {{ invoice.total }} ? Balance: {{ invoice.balance }}</p></div><template v-if="['issued','partially_paid','overdue'].includes(invoice.status)"><form class="form-card mt-6" @submit.prevent="pay.post(route('partner.invoices.pay',invoice.uuid))"><h2 class="text-xl font-bold">Online payment</h2><FormErrors :errors="pay.errors"/><button class="form-button" :disabled="pay.processing">Pay {{ invoice.currency }} {{ invoice.balance }} with Flutterwave</button></form><form class="form-card mt-6" @submit.prevent="manual.post(route('partner.payments.store',invoice.uuid),{preserveScroll:true,onSuccess:()=>manual.reset('transaction_reference')})"><h2 class="text-xl font-bold">Submit an offline payment</h2><p class="text-sm text-slate-600">Finance must verify this payment before it settles the invoice or earns commission.</p><FormErrors :errors="manual.errors"/><div class="form-grid"><label>Amount<input v-model="manual.amount" type="number" min="0.01" step="0.01" :max="invoice.balance" required/></label><label>Method<select v-model="manual.payment_method"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="pos">POS</option></select></label><label>Transaction reference<input v-model="manual.transaction_reference" required maxlength="255"/></label><label>Payment date<input v-model="manual.payment_date" type="date" required/></label></div><button class="form-button" :disabled="manual.processing">Submit for verification</button></form></template></PartnerLayout></template>
